const FRAMES = GRID.frames
/** Frames of one beat (the CTA nudge, the end card's next beat). */
export const BEAT_FRAMES = Math.round(GRID.period * 30)
/** Kit clips: CSS viewport (editor and site). The camera plane of every UI shot. */
export const VP = { w: 1280, h: 1440 }
/** Motion-built planes (C8 PDF sheets, C12 end card): output px. */
export const OUT_PLANE = { w: 1080, h: 1920 }
/** Frame of beat `beat` (halves interpolate) plus `offset` frames. */
const bf = (beat, offset = 0) => gridBeatFrame(GRID, beat, offset)

// ---------------------------------------------------------------- clip data access

const clip = (id) => {
  const c = CLIP_DATA[id]
  if (!c)
    throw new Error(
      `c.shots.js: no clip data for ${id} (run walks-c.mjs --pack)`,
    )
  return c
}
const clampF = (id, f) =>
  Math.max(0, Math.min(clip(id).frames - 1, Math.round(f)))
/** Frame of the `k`-th pointer event of `type` (down | up | key) in clip `id`. */
const ev = (id, type, k = 0) => {
  const e = clip(id).events.filter((x) => x[1] === type)[k]
  if (!e) throw new Error(`c.shots.js: ${id} has no ${type} #${k}`)
  return e[0]
}
const asBox = (r) => (r ? { x: r[0], y: r[1], w: r[2], h: r[3] } : null)
/** Raw value of rect `name` at clip frame `f` (CLIP_DATA keeps runs `[[first frame, value], …]`). */
const rectRaw = (id, name, f) => {
  const runs = clip(id).rects[name]
  if (!runs) throw new Error(`c.shots.js: ${id} has no rect ${name}`)
  const k = clampF(id, f)
  let v = null
  for (const [f0, value] of runs) {
    if (f0 > k) break
    v = value
  }
  return v
}
/** Rect `name` (box | k-th box of an `all` target) at clip frame `f`. */
export const rect = (id, name, f, k) => {
  const r = rectRaw(id, name, f)
  return asBox(k == null ? r : r?.[k])
}
export const pointerAt = (id, f) => {
  const p = clip(id).ptr[clampF(id, f)]
  return { x: p[0], y: p[1], down: !!p[2] }
}
export const centre = (b) => ({ x: b.x + b.w / 2, y: b.y + b.h / 2 })
const union = (...bs) => {
  const v = bs.filter(Boolean)
  const x = Math.min(...v.map((b) => b.x))
  const y = Math.min(...v.map((b) => b.y))
  return {
    x,
    y,
    w: Math.max(...v.map((b) => b.x + b.w)) - x,
    h: Math.max(...v.map((b) => b.y + b.h)) - y,
  }
}
const pad = (b, p) => ({
  x: b.x - p,
  y: b.y - p,
  w: b.w + 2 * p,
  h: b.h + 2 * p,
})

/** A 9:16 crop `{cx, cy, w}` kept inside the plane (no ground edge from the clip plane). */
function crop(cx, cy, w, plane = VP) {
  const h = (w * 16) / 9
  return {
    cx: Math.min(plane.w - w / 2, Math.max(w / 2, cx)),
    cy:
      h > plane.h
        ? plane.h / 2
        : Math.min(plane.h - h / 2, Math.max(h / 2, cy)),
    w,
  }
}

/** Output px of plane point `p` in `shot` at `frame` (whip offset included). */
export function outPoint(shot, frame, p) {
  const { s, tx, ty } = cameraAt(shot, frame)
  return { x: p.x * s + tx + whipOffset(shot, frame), y: p.y * s + ty }
}

// ---------------------------------------------------------------- whip pans (§2: 7 frames, 1600 px, cut in the middle)

export const WHIP = { frames: 7, distance: 1600 }
const easeInOut = (t) => (t < 0.5 ? 4 * t * t * t : 1 - (-2 * t + 2) ** 3 / 2)
/** Horizontal output offset of a whip: the outgoing shot leaves left over its last 3 frames, the incoming one arrives
 *  from the right over its first 4 (the cut is the whip's middle frame). */
export function whipOffset(shot, frame) {
  const half = WHIP.distance / 2
  if (shot.whipIn) {
    const k = frame - shot.from
    if (k >= 0 && k < 4)
      return half * (1 - easeInOut((k + 3) / WHIP.frames)) * 2
  }
  if (shot.whipOut) {
    const k = frame - (shot.to - 3)
    if (k >= 0 && k < 3) return -half * easeInOut((k + 1) / WHIP.frames) * 2
  }
  return 0
}

// ---------------------------------------------------------------- drag flights (v2 G5)

/** A dragged photo is 62 % of its target frame's width (v2 G5); after the release it springs (`light`) onto the
 *  frame. `drag` = { clip, file, target (plane box), down, up (reel frames) }. */
export const DRAG_SHARE = 0.62

const UI = (id, at) => ({ clip: id, rate: 1, at, start: at })

/** Reel frame of clip event `e` in a shot that starts at `from` and plays clip frame `at` there. */
const reelOf = (from, at, clipFrame) => clipFrame - at + from

/** Asserts that `got` is within one frame of `want` (the clip's spacing vs the track's 14.23-frame beat). */
function onBeat(what, got, want) {
  if (Math.abs(got - want) > 1)
    throw new Error(`${what} at frame ${got}, want ${want} ± 1`)
}

