/** The shelf take (site books=30): the plate (C9), the click on "Desert road" (C10), the room: two clicked turns to
 *  pages 4–5, the breath drag back onto the full-bleed 2–3 (C11), the hold (C12), the teaser turn (C1). Mappings
 *  (clip frame = reel frame − offset): C10 SHELF_AT; C11 and C12 ROOM_AT (the breath press on b29); C1 SHELF_TEASE
 *  (the teaser click on frame 4). The `down` events in order: shelf click, turn, turn, breath, teaser. */
const SHELF = 'c-shelf'
const SHELF_AT = 256
const DOWN = { shelf: 0, turn1: 1, turn2: 2, breath: 3, teaser: 4 }
const shelfDown = (k) => ev(SHELF, 'down', DOWN[k])
const ROOM_AT = bf(29) - shelfDown('breath')
const SHELF_TEASE = shelfDown('teaser') - 4

