export const END_BOOK = { x: 79.2, y: 383.3, w: 1121.2, h: 674 }
/** Room shown around END_BOOK (CSS px): 44 on three sides; at the bottom only the board's 7.4 px edge, so the dark
 *  board meets the dark ground and the pages' bottom is the one edge there (a lit strip under the board would give
 *  check 10 two edges 5 output px apart, and the stronger one changes with the scale). */
export const END_MARGIN = { top: 44, right: 44, bottom: 7.4, left: 44 }
export const ROOM_PHOTO = { x: 110, y: 375, w: 1086, h: 686 }
const ROOM_LEFT = { ...ROOM_PHOTO, w: ROOM_PHOTO.w / 2 - 8 }
export const PAGES_45 = [
  { x: 158, y: 440, w: 428, h: 540 },
  { x: 690, y: 440, w: 436, h: 540 },
]
/** Frames of a clicked leaf turn (820 ms) and of the breath's drag turn (1300 ms). */
const LEAF = 25
const BREATH = 39
const roomBook = () => ROOM_BOOK

/**
 * The photo on the room's pages at clip frame `f`, as `data-photo` boxes (the GL pages have no DOM). A turn from 2–3
 * to 4–5 (either way) keeps page 2's half of the spread and page 5's framed photo in view until the leaf lands.
 */
function roomPhotosAt(f) {
  const spread = [{ ...ROOM_PHOTO, id: 'spread-2-3' }]
  const half = [
    { ...ROOM_LEFT, id: 'page-2' },
    { ...PAGES_45[1], id: 'page-5' },
  ]
  const framed = PAGES_45.map((b, k) => ({ ...b, id: `page-${4 + k}` }))
  const t1 = shelfDown('turn1')
  const t2 = shelfDown('turn2')
  const b = shelfDown('breath')
  const tz = shelfDown('teaser')
  if (f < t1 + LEAF) return []
  if (f < t2) return spread
  if (f < t2 + LEAF) return half
  if (f < b) return framed
  if (f < b + BREATH) return half
  if (f < tz) return spread
  if (f < tz + LEAF) return half
  return framed
}
const roomPhoto = (from, at) => (f) => roomPhotosAt(f - from + at)

function shotC1() {
  // C1 Md teaser: the finished book in the reading room, one clicked page turn; the camera follows the leaf from the
  // right page to the left one (v2 G3: one page ≥ 900 px wide)
  const from = 0
  const click = reelOf(from, SHELF_TEASE, shelfDown('teaser'))
  onBeat('C1 teaser click', click, 4)
  const book = roomBook(SHELF_TEASE)
  const page = book.w / 2
  const w = 600
  return {
    id: 'C1',
    from,
    to: bf(2),
    scale: 'Md',
    ui: UI(SHELF, SHELF_TEASE),
    room: true,
    photoBoxes: roomPhoto(from, SHELF_TEASE),
    cam: [
      crop(book.x + page * 1.5, book.y + book.h / 2, w),
      crop(book.x + page * 0.62, book.y + book.h / 2 + 6, w - 20),
    ],
    drift: { x: -6, y: 0 },
    push: 0.01,
    ground: 'T7.jpg',
    marks: { click },
  }
}

function shotC2() {
  // C2 M, UI-only (≤ 0.6 s): the picker's Choose, the click 3 frames in, the strip full on the next frame
  const id = 'c-open'
  const from = bf(2)
  const at = ev(id, 'down') - 3
  const click = reelOf(from, at, ev(id, 'down'))
  const choose = rect(id, 'choose', at) ?? rect(id, 'dialog', at)
  const strip = rect(id, 'filmstrip', at + 6)
  const w = 480
  const h = (w * 16) / 9
  // Choose in the upper third, the strip at the bottom
  const top = Math.min(choose.y - 60, strip.y + strip.h + 24 - h)
  const cx = centre(choose).x - 60
  return {
    id: 'C2',
    from,
    to: bf(3),
    scale: 'M',
    uiOnly: true,
    ui: UI(id, at),
    cam: [crop(cx, top + h / 2, w), crop(cx + 6, top + h / 2 + 8, w - 16)],
    drift: { x: -6, y: 0 },
    push: 0.012,
    focus: (f) => (f <= click ? pad(choose, 10) : strip),
    marks: { click },
  }
}

function shotC3() {
  // C3 Md: T7 already in flight from the strip, dropped onto spread 1's big frame on b4.5, `light` landing
  const id = 'c-drop'
  const from = bf(3)
  const drop = bf(4.5)
  const at = ev(id, 'up') - (drop - from)
  const target = rect(id, 'frame', ev(id, 'up') + 6, 0)
  const spread = rect(id, 'spread', ev(id, 'up') + 6)
  const c = centre(spread)
  const w = 780
  return {
    id: 'C3',
    from,
    to: bf(7),
    scale: 'Md',
    ui: UI(id, at),
    cam: [crop(c.x, 720, w), crop(c.x + 8, 716, w - 16)],
    drift: { x: 6, y: 0 },
    push: 0.01,
    drag: {
      file: 'T7.jpg',
      target,
      down: reelOf(from, at, ev(id, 'down')),
      up: drop,
    },
    photos: [
      { file: 'T7.jpg', outW: Math.ceil(target.w * (1080 / 764) * 1.1) },
    ],
    focus: (f) => {
      // the lit box reaches over the rotate handle above the frame, so the
      // focus edge never crosses the handle (check 10); the card is gone on
      // the release frame (ReelC DragCard)
      const lit = { ...pad(target, 8), y: target.y - 40, h: target.h + 48 }
      if (f >= drop) return lit
      const p = pointerAt(id, f - from + at)
      const cw = target.w * DRAG_SHARE
      const ch = (cw * target.h) / target.w
      return union(lit, {
        x: p.x - cw / 2,
        y: p.y - ch / 2,
        w: cw,
        h: ch,
      })
    },
    marks: { drop },
  }
}

function shotC4() {
  // C4 M: macro on the layout pill + spread: Next on b8, 8.5, 9, 9.5 (233 ms apart), each layout instant + punch
  const id = 'c-layouts'
  const from = bf(7)
  const first = bf(8)
  const at = ev(id, 'down') - (first - from)
  const downs = [0, 1, 2, 3].map((k) => reelOf(from, at, ev(id, 'down', k)))
  downs.forEach((d, k) => onBeat(`C4 click ${k}`, d, bf(8 + k / 2)))
  const next = rect(id, 'next', at)
  const pill = rect(id, 'pill', at)
  const spread = rect(id, 'spread', at)
  const w = 460
  const h = (w * 16) / 9
  return {
    id: 'C4',
    from,
    to: bf(11),
    scale: 'M',
    ui: UI(id, at),
    // Next at ~40 % from the left, the pill at ~22 % from the top, the spread's photo below it
    cam: [
      crop(next.x + 30, pill.y + h * 0.28, w),
      crop(next.x + 40, pill.y + h * 0.29, w - 20),
    ],
    drift: { x: -5, y: 0 },
    push: 0.008,
    // the layout shows on the frame after the release (down + 3)
    punches: downs.map((d) => ({ frame: d + 3, amount: 0.02 })),
    photos: [
      { file: 'T7.jpg', outW: Math.ceil(spread.w * (1080 / 440) * 1.12) },
    ],
    focus: (f) => union(pill, rect(id, 'spread', f - from + at)),
    marks: { downs },
  }
}

/** C5 crop of width `w` that puts the centre of `chip` at output y 1490 (the stack above it). */
function chipCrop(cx, chip, w) {
  const s = 1080 / w
  return { ...crop(cx, 720, w), cy: chip.y + chip.h / 2 - 530 / s }
}

function shotC5() {
  // C5 W: the stack + chip row: Fill book chip b11, Enter b12 = the lift bar's downbeat (every spread fills)
  const id = 'c-fill'
  const from = bf(11)
  const at = ev(id, 'down')
  const enter = reelOf(from, at, ev(id, 'key'))
  onBeat('C5 Enter (lift bar)', enter, bf(GRID.liftBar * 4))
  const chip = rect(id, 'chip', at)
  const spread = rect(id, 'spread', at)
  const cx = (centre(spread).x + centre(chip).x) / 2
  return {
    id: 'C5',
    from,
    to: bf(13),
    scale: 'W',
    ui: UI(id, at),
    // the chip sits at the kit's bottom edge: frame it at output y ≈ 1490 (safe zone); the ground shows below
    cam: [chipCrop(cx, chip, 800), chipCrop(cx - 6, chip, 776)],
    drift: { x: -6, y: 0 },
    // 0.012: over 28 frames the ease-out and the punch's settle cancel a 0.008 push on the last frame (check 4)
    push: 0.012,
    punches: [{ frame: enter + 1, amount: 0.02 }],
    whipOut: true,
    fast: [{ from: bf(13) - 3, to: bf(13) }],
    ground: 'T7.jpg',
    marks: { chip: from, enter },
  }
}

function shotC6() {
  // C6 M: whip in; macro on the cover's front board, T14 dragged up from the strip lands on b14, replacing T7
  // (b13–b15: cuts sit on whole beats (check 2 + reels-mix 12g); C7 needs b15–b16, the one beat here that rounds to
  // 15 frames, so C6 starts a beat early)
  const id = 'c-cover'
  const from = bf(13)
  const drop = bf(14)
  const at = ev(id, 'up') - (drop - from)
  const front = rect(id, 'front', ev(id, 'up') + 6)
  const c = centre(front)
  const w = 470
  return {
    id: 'C6',
    from,
    to: bf(15),
    scale: 'M',
    ui: UI(id, at),
    cam: [crop(c.x, c.y + 70, w), crop(c.x + 6, c.y + 60, w - 18)],
    drift: { x: 5, y: 0 },
    push: 0.01,
    whipIn: true,
    fast: [{ from, to: from + 4 }],
    drag: {
      file: 'T14.jpg',
      target: front,
      down: reelOf(from, at, ev(id, 'down')),
      up: drop,
    },
    photos: [
      { file: 'T14.jpg', outW: Math.ceil(front.w * (1080 / 452) * 1.1) },
    ],
    focus: () => pad(front, 10),
    marks: { drop },
  }
}

function shotC7() {
  // C7 Md, UI-only (0.5 s): the print dialog (opened off camera once its preflight finished); Export pressed 10
  // frames in, the cut 5 frames later comes before the release (the job starts on release: no running state).
  // b15–b16: one beat that rounds to 15 frames on this grid (b16–b17 is 14, under check 2's 0.5 s)
  const id = 'c-print'
  const from = bf(15)
  const to = bf(16)
  const press = from + 10
  const at = ev(id, 'down') - (press - from)
  const dialog = rect(id, 'printDialog', at) ?? rect(id, 'dialog', at)
  const c = centre(dialog)
  return {
    id: 'C7',
    from,
    to,
    scale: 'Md',
    uiOnly: true,
    ui: UI(id, at),
    cam: [crop(c.x + 40, c.y, 780), crop(c.x + 30, c.y, 760)],
    drift: { x: -6, y: 0 },
    push: 0.012,
    focus: () => pad(dialog, 6),
    marks: { press },
  }
}

/** C8: three PDF pages (cover sheet + 2 spreads) built on the product's print geometry, stacked top to bottom, each
 *  ≥ 880 px wide (v2 G3); they slam in from below and land one per half-beat. Book 146 × 210 mm, spine 6 mm (20
 *  pages, Generic profile). Output px. */
export const PDF_PX_PER_MM = 2.9
/** Frames from a sheet's start to its landing (the `medium` spring first reaches its place). */
const landFrames = (weight) => {
  for (let k = 1; k < 60; k++) if (springAt(k, weight) >= 1) return k
  return 60
}
export const SHEET_LAND = landFrames('medium')
export const PDF_PAGES = [
  {
    kind: 'cover',
    trimW: 298,
    trimH: 210,
    spine: 6,
    spineX: 146,
    photos: ['T7.jpg', 'T14.jpg'],
    land: bf(16.5),
    y: 24,
  },
  {
    kind: 'spread',
    trimW: 292,
    trimH: 210,
    photos: ['T7.jpg'],
    land: bf(17),
    y: 640,
  },
  {
    kind: 'spread',
    trimW: 292,
    trimH: 210,
    photos: ['T1.jpg', 'T3.jpg'],
    land: bf(17.5),
    y: 1256,
  },
].map((p) => ({ ...p, at: p.land - SHEET_LAND }))

function shotC8() {
  const from = bf(16)
  return {
    id: 'C8',
    from,
    to: bf(20),
    scale: 'M',
    plane: OUT_PLANE,
    pdf: PDF_PAGES,
    cam: [crop(540, 960, 1080, OUT_PLANE), crop(540, 950, 1050, OUT_PLANE)],
    drift: { x: 0, y: -8 },
    push: 0.008,
    whipOut: true,
    fast: [{ from: bf(20) - 3, to: bf(20) }],
    ground: 'T7.jpg',
    photos: [
      { file: 'T7.jpg', outW: Math.ceil(298 * PDF_PX_PER_MM * 1.06) },
      { file: 'T14.jpg', outW: Math.ceil(149 * PDF_PX_PER_MM * 1.06) },
      { file: 'T1.jpg', outW: Math.ceil(149 * PDF_PX_PER_MM * 1.06) },
      { file: 'T3.jpg', outW: Math.ceil(149 * PDF_PX_PER_MM * 1.06) },
    ],
  }
}

/** Spine books that drop in on C9 (index into `books`), one per beat; the face-out "Desert road" is already there. */
export const SHELF_DROPS = [1, 2, 3, 4]
/** Frames from a C9 book's drop start to its landing (the `heavy` spring first reaches its place). */
export const DROP_LAND = landFrames('heavy')

function shotC9() {
  // C9 W, the hard cut to the light site on the downbeat b20: the case, books drop onto their places on b20–b23
  const from = bf(20)
  const all = rectRaw(SHELF, 'books', 0).map(asBox)
  const face = all[0]
  // the wall gap between the face-out cover and the first spine: the slot patches' colour source
  const patchX = Math.round((face.x + face.w + all[1].x) / 2)
  // the top two shelves: both face-out covers (the second is on the shelf below)
  const w = 700
  return {
    id: 'C9',
    from,
    to: bf(24),
    scale: 'W',
    ui: UI(SHELF, 0),
    cam: [
      crop(face.x + w / 2 - 40, face.y + (w * 16) / 9 / 2 - 140, w),
      crop(face.x + w / 2 - 50, face.y + (w * 16) / 9 / 2 - 150, w - 16),
    ],
    drift: { x: -6, y: 0 },
    push: 0.008,
    drops: SHELF_DROPS.map((k, i) => ({ box: all[k], from: bf(20 + i) })),
    patchX,
    marks: { face },
  }
}

function shotC10() {
  // C10 M: macro on "Desert road": hover lift, click on b25
  const from = bf(24)
  const click = reelOf(from, from - SHELF_AT, shelfDown('shelf'))
  onBeat('C10 shelf click', click, bf(25))
  const face = rect(SHELF, 'desert', 0)
  const c = centre(face)
  return {
    id: 'C10',
    from,
    to: bf(26),
    scale: 'M',
    ui: UI(SHELF, from - SHELF_AT),
    cam: [crop(c.x, c.y + 20, 440), crop(c.x + 6, c.y + 16, 424)],
    drift: { x: -5, y: 0 },
    push: 0.012,
    focus: () => pad(face, 12),
    marks: { click },
  }
}

function shotC11() {
  // C11 Md: the room, cut in as the leaf lands on 4–5; on b29 the breath, a 1300 ms drag turn back onto the
  // full-bleed 2–3; the camera holds one page ≥ 900 px wide and follows the leaf from the left page to the right one
  const from = bf(26)
  const at = from - ROOM_AT
  const breath = reelOf(from, at, shelfDown('breath'))
  onBeat('C11 breath drag', breath, bf(29))
  const book = roomBook()
  const page = book.w / 2
  const cy = book.y + book.h / 2
  return {
    id: 'C11',
    from,
    to: bf(32),
    scale: 'Md',
    ui: UI(SHELF, at),
    room: true,
    photoBoxes: roomPhoto(from, at),
    cam: [
      crop(book.x + page * 0.55, cy, 640),
      crop(book.x + page * 1.4, cy + 8, 620),
    ],
    drift: { x: 0, y: -6 },
    push: 0.004,
    // the 1300 ms drag turn (39 frames)
    breath: { from: breath, to: breath + 39 },
    ground: 'T7.jpg',
    marks: { breath },
  }
}

function shotC12(prev) {
  // end card: the open spread (as C11 leaves it) eases into the end box above the text, on a margin of the lit room;
  // output-px plane
  const book = END_BOOK
  const k = cameraAt(prev, prev.to)
  const start = {
    x: book.x * k.s + k.tx,
    y: book.y * k.s + k.ty,
    w: book.w * k.s,
    h: book.h * k.s,
  }
  return {
    id: 'C12',
    from: bf(32),
    to: FRAMES,
    scale: 'end',
    plane: OUT_PLANE,
    end: {
      clip: SHELF,
      // one frame of the spread at rest, 1.5 s after the breath's leaf lands: the leaf still settles for ~0.5 s
      // after it (the board / page shading moves under check 10's gutter measure); the heavy spring and the camera
      // push carry the motion
      frame: shelfDown('breath') + BREATH + 44,
      book,
      rect: start,
      margin: END_MARGIN,
    },
    cam: [crop(540, 960, 1080, OUT_PLANE), crop(540, 960, 1074, OUT_PLANE)],
    drift: { x: 0, y: -4 },
    push: 0.005,
    ground: 'T7.jpg',
  }
}

function buildShots() {
  const shots = [
    shotC1(),
    shotC2(),
    shotC3(),
    shotC4(),
    shotC5(),
    shotC6(),
    shotC7(),
    shotC8(),
    shotC9(),
    shotC10(),
    shotC11(),
  ]
  shots.push(shotC12(shots.at(-1)))
  return shots
}

const byId = (shots, id) => shots.find((s) => s.id === id)

/**
 * The foley cue list (reels-mix.mjs CUES types; spec v2 §3 «Foley cues»): `{ frame, type, x, y? }`, x / y = the
 * output point (pan, check 6 safe zone). `beat` is the grid beat the cue sits on (reels-render check 2 reads it).
 */
function buildCues(shots) {
  const at = (id, frame, p) => {
    const o = outPoint(byId(shots, id), frame, p)
    return { x: Math.round(o.x), y: Math.round(o.y) }
  }
  const ptr = (id, frame) => {
    const s = byId(shots, id)
    return at(id, frame, pointerAt(s.ui.clip, frame - s.from + s.ui.at))
  }
  // every cue names the grid beat it hangs on; `offset` = frames past it (less than a beat: a cue placed off its beat
  // by a re-timing throws here instead of drifting)
  const cue = (frame, beat, type, extra = {}) => {
    const offset = frame - bf(beat)
    if (Math.abs(offset) >= BEAT_FRAMES)
      throw new Error(
        `cue ${type} at frame ${frame} is ${offset} f off b${beat}`,
      )
    return { frame, beat, offset, type, sfx: type, ...extra }
  }
  const S = Object.fromEntries(shots.map((s) => [s.id, s]))
  const C3 = S.C3
  const C6 = S.C6
  return [
    cue(S.C1.marks.click, 0, 'page', { x: 760 }),
    cue(S.C2.marks.click, 2, 'click', ptr('C2', S.C2.marks.click)),
    cue(
      C3.marks.drop,
      4.5,
      'drop',
      at('C3', C3.marks.drop, centre(C3.drag.target)),
    ),
    ...S.C4.marks.downs.map((d, k) => cue(d, 8 + k / 2, 'click', ptr('C4', d))),
    cue(S.C5.marks.chip, 11, 'click', ptr('C5', S.C5.marks.chip)),
    cue(S.C5.marks.enter, GRID.liftBar * 4, 'key', { x: 540 }),
    cue(S.C5.marks.enter + 1, GRID.liftBar * 4, 'fill', { x: 540 }),
    cue(S.C5.to - 2, 13, 'swish', { x: 300 }),
    cue(
      C6.marks.drop,
      14,
      'drop',
      at('C6', C6.marks.drop, centre(C6.drag.target)),
    ),
    cue(S.C7.marks.press, 15, 'click', ptr('C7', S.C7.marks.press)),
    ...PDF_PAGES.map((p, k) =>
      cue(p.land, 16.5 + k / 2, k ? 'drop' : 'cover', { x: 540 }),
    ),
    cue(S.C8.to - 2, 20, 'swish', { x: 300 }),
    ...S.C9.drops.map((d, i) =>
      cue(
        d.from + DROP_LAND,
        20 + i,
        'wood',
        at('C9', d.from + DROP_LAND, centre(d.box)),
      ),
    ),
    cue(S.C10.marks.click, 25, 'click', ptr('C10', S.C10.marks.click)),
    // the cover swings open over 1000 ms from the click (seen at the end of C10); C11 cuts in on a leaf in flight
    cue(S.C10.marks.click + 7, 25, 'cover', { x: 600 }),
    cue(S.C11.from, 26, 'page', { x: 640 }),
    cue(S.C11.breath.from, 29, 'pageSlow', { x: 600 }),
    cue(S.C11.breath.from, 29, 'breath', { x: 540, frames: 39 }),
    cue(S.C12.from, 32, 'impact', { x: 540 }),
  ].sort((a, b) => a.frame - b.frame)
}

const shots = Object.keys(CLIP_DATA).length ? buildShots() : []
const cues = shots.length ? buildCues(shots) : []

export default {
  reel: R,
  frames: FRAMES,
  plane: VP,
  grid: GRID,
  shots,
  cues,
  /** reels-mix.mjs `--cues` input: the cut frames (check 12g) and the foley cues. */
  sound: {
    frames: FRAMES,
    cuts: shots.slice(1).map((s) => s.from),
    cues: cues.map(({ frame, type, x, frames }) =>
      frames ? { frame, type, x, frames } : { frame, type, x },
    ),
  },
}
